package ru.voboost.voyemu;
import static org.junit.jupiter.api.Assertions.*;
import java.awt.*;import java.awt.image.*;import java.io.IOException;import java.nio.file.*;import javax.imageio.ImageIO;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.io.TempDir;
class GlyphRasterOracleTest {
 @TempDir Path work;
 static Path components()throws IOException{return Path.of("../voboost-components").toRealPath();}
 static Path hardware()throws IOException{return components().resolve("src/demo-pixel/java/ru/voboost/components/demo/pixel/MainActivity.screenshots/button-01-free-dark_1original.png");}
 PixelImage png(BufferedImage image,String name)throws Exception{Path file=work.resolve(name+".png");ImageIO.write(image,"png",file.toFile());return PixelImage.read(file,image.getWidth(),image.getHeight());}
 BufferedImage crop()throws Exception{var source=ImageIO.read(hardware().toFile());var result=new BufferedImage(250,70,BufferedImage.TYPE_INT_RGB);var g=result.createGraphics();g.drawImage(source.getSubimage(515,84,250,70),0,0,null);g.dispose();return result;}
 @Test void immutableHardwareCaptionsCalibrateAndPassWithoutApprovingProductScreen()throws Exception {var c=GlyphRasterOracle.calibrate(components());assertEquals(2,c.edgeRadius());var image=PixelImage.read(hardware(),1920,720);var p=GlyphRasterOracle.button(image,515,84,250,70,"Factory reset",c);assertTrue(p.get("rasterMatch").getAsBoolean());assertFalse(p.get("functionalAcceptance").getAsBoolean());assertFalse(p.get("publicationApproval").getAsBoolean());assertTrue(GlyphRasterOracle.button(image,515,342,150,70,"Check",c).get("rasterMatch").getAsBoolean());}
 @Test void missingGlyphClippingAndWrongSpacingCannotPassTheHardwareOracle()throws Exception {var c=GlyphRasterOracle.calibrate(components());for(String mutation:new String[]{"missing","clip","spacing","blank"}){var image=crop();var g=image.createGraphics();g.setColor(new Color(0x373f4a));switch(mutation){case "missing"->g.fillRect(44,20,20,35);case "clip"->g.fillRect(160,15,60,40);case "blank"->g.fillRect(20,10,210,50);case "spacing"->{var copy=crop();g.fillRect(100,10,120,50);g.drawImage(copy.getSubimage(100,10,115,50),107,10,null);}}g.dispose();var actual=png(image,mutation);assertThrows(IOException.class,()->GlyphRasterOracle.button(actual,0,0,250,70,"Factory reset",c),mutation);}}
 @Test void wrongFontAndWrongCaptionAreRejectedEvenWhenBoundingBoxIsValid()throws Exception {var c=GlyphRasterOracle.calibrate(components());var image=crop();var g=image.createGraphics();g.setColor(new Color(0x373f4a));g.fillRect(20,10,210,50);g.setColor(Color.WHITE);g.setFont(new Font(Font.MONOSPACED,Font.BOLD,28));g.drawString("Factory reset",23,45);g.dispose();var actual=png(image,"wrong-font");assertThrows(IOException.class,()->GlyphRasterOracle.button(actual,0,0,250,70,"Factory reset",c));var good=PixelImage.read(hardware(),1920,720);assertThrows(IOException.class,()->GlyphRasterOracle.button(good,515,84,250,70,"Factory",c));}
 @Test void uncalibratedUnsupportedGlyphAndWrongRoiAreNotAVisualPass()throws Exception {var c=GlyphRasterOracle.calibrate(components());var image=PixelImage.read(hardware(),1920,720);assertThrows(IOException.class,()->GlyphRasterOracle.button(image,515,84,250,70,"Factory reset",null));assertThrows(IOException.class,()->GlyphRasterOracle.button(image,515,84,250,70,"卸载Voboost",c));assertThrows(IOException.class,()->GlyphRasterOracle.button(image,515,84,250,69,"Factory reset",c));}
 @Test void exactHardwareCheckboxStateRejectsOtherStateAndChangedPixels()throws Exception {var c=GlyphRasterOracle.calibrate(components());var file=hardware().resolveSibling("checkbox-01-free-dark_1original.png");var image=PixelImage.read(file,1920,720);assertTrue(GlyphRasterOracle.checkbox(image,516,191,false,c).get("rasterMatch").getAsBoolean());assertTrue(GlyphRasterOracle.checkbox(image,516,598,true,c).get("rasterMatch").getAsBoolean());assertThrows(IOException.class,()->GlyphRasterOracle.checkbox(image,516,191,true,c));var altered=ImageIO.read(file.toFile()).getSubimage(516,191,83,42);altered.setRGB(40,20,0xfff00000);var bad=png(altered,"altered-checkbox");assertThrows(IOException.class,()->GlyphRasterOracle.checkbox(bad,0,0,false,c));}

}
